# Ordem dos temas da 4.2 antes da ordem livre, para os laudos antigos continuarem como estavam.
ORDEM_ANTIGA = [
    "trajetoria_escolar", "cognicao", "rotina", "comportamento", "interesses", "sensorial", "social",
    "relacionamentos", "humor", "ansiedade", "alimentacao", "sono", "outro",
    "saude", "medicacao", "historico_familiar", "profissionais",
]


def fixar_ordem_da_anamnese(apps, schema_editor):
    """Na 4.2, posicao passou a ser a ordem na seção. Grava nela a ordem que cada laudo já mostrava."""
    Paragrafo = apps.get_model("laudos", "Paragrafo")
    ordem = {tema: i for i, tema in enumerate(ORDEM_ANTIGA)}
    laudos = Paragrafo.objects.filter(secao="4.2").values_list("laudo_id", flat=True).distinct()
    for laudo_id in laudos:
        paragrafos = list(Paragrafo.objects.filter(secao="4.2", laudo_id=laudo_id))
        paragrafos.sort(key=lambda p: (ordem.get(p.tema, 99), p.posicao, p.id))
        for i, p in enumerate(paragrafos):
            if p.posicao != i:
                p.posicao = i
                p.save(update_fields=["posicao"])


